/**
 * Unit tests for XmlSerializerProvider constructor.
 * Since the constructor is protected, we use a Test subclass to access it.
 */
public class XmlSerializerProvider_XmlSerializerProvider_TriageGen0Test {

    /**
     * A subclass to expose the protected constructor for testing.
     */
    private static class TestableXmlSerializerProvider extends XmlSerializerProvider {

        protected TestableXmlSerializerProvider(XmlRootNameLookup rootNames) {
            super(rootNames);
        }

        protected TestableXmlSerializerProvider(XmlSerializerProvider src) {
            super(src);
        }

        public XmlRootNameLookup getRootNameLookup() {
            // Accessing the field via reflection if it were private, 
            // but since we are in the same package and testing the logic, 
            // we assume we can verify the state.
            // In Jackson, _rootNameLookup is protected.
            return this._rootNameLookup;
        }
    }

    @Test
    public void testProtectedConstructor_CopiesRootNameLookup() {
        // Arrange
        XmlRootNameLookup mockLookup = mock(XmlRootNameLookup.class);
        XmlSerializerProvider src = new TestableXmlSerializerProvider(mockLookup);

        // Act
        TestableXmlSerializerProvider target = new TestableXmlSerializerProvider(src);

        // Assert
        // The logic states: _rootNameLookup = src._rootNameLookup;
        // We verify that the reference is the same (shallow copy as per requirement)
        assertSame("The _rootNameLookup should be the same instance as the source's _rootNameLookup",
                src.getRootNameLookup(), target.getRootNameLookup());
    }

    @Test
    public void testProtectedConstructor_WithNullLookup() {
        // Arrange
        XmlSerializerProvider src = new TestableXmlSerializerProvider(null);

        // Act
        TestableXmlSerializerProvider target = new TestableXmlSerializerProvider(src);

        // Assert
        assertEquals("The _rootNameLookup should be null if the source's lookup is null",
                null, target.getRootNameLookup());
    }

    @Test
    public void testPublicConstructor_XmlRootNameLookup() {
        // Arrange
        XmlRootNameLookup mockLookup = mock(XmlRootNameLookup.class);

        // Act
        TestableXmlSerializerProvider target = new TestableXmlSerializerProvider(mockLookup);

        // Assert
        assertSame("The root name lookup should be set correctly via public constructor",
                mockLookup, target.getRootNameLookup());
    }
}
